
public class looping_statements {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i =1;
		
		while(i<6)
		{
			System.out.println("Hi " + i);
			i++;
		}
		
		do {
			System.out.println("Helllo");
		}while(i<6);
		
		for(int y = 0 ; y < 5 ; y++) {
			System.out.println("Hi " + (y+1));
		}
		
		

	}

}
